Backup code must handle a hostile filesystem; simulate every failure with monkeypatching. Save /workspace/backup.py:

import os
import shutil

def backup_files(src_dir, dst_dir, log):
    copied, skipped, failed = 0, 0, 0
    os.makedirs(dst_dir, exist_ok=True)
    for name in sorted(os.listdir(src_dir)):
        src = os.path.join(src_dir, name)
        if not os.path.isfile(src):
            skipped += 1
            continue
        dst = os.path.join(dst_dir, name)
        try:
            if os.path.exists(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
                skipped += 1
                continue
            shutil.copy2(src, dst)
            copied += 1
        except PermissionError:
            log.append(f"permission denied: {name}")
            failed += 1
        except OSError as e:
            log.append(f"os error on {name}: {e.errno}")
            failed += 1
    return {"copied": copied, "skipped": skipped, "failed": failed}

